<?php
declare(strict_types=1);
namespace QualitySystem\Repositories;
use PDO;
final class ProgramManualRepository{
    public function __construct(private readonly PDO $pdo){}
    private function scope(string $role,int $user,array &$params,string $alias='pm'):string{if(in_array($role,['Admin','Quality Coordinator'],true))return'1=1';$params[':manual_scope_user']=$user;return"$alias.program_specification_id IN (SELECT program_specification_id FROM user_program_access WHERE user_id=:manual_scope_user)";}
    public function all(string $role,int $user):array{$p=[];$scope=$this->scope($role,$user,$p);$s=$this->pdo->prepare("SELECT pm.*,ps.program_name,ps.program_code,(SELECT COUNT(*) FROM program_manual_sections x WHERE x.program_manual_id=pm.id) section_count,(SELECT COUNT(*) FROM program_manual_reconciliations r WHERE r.program_manual_id=pm.id AND r.resolution='Unresolved') unresolved_count FROM program_manuals pm JOIN program_specifications ps ON ps.id=pm.program_specification_id WHERE $scope ORDER BY pm.next_review_date IS NULL,pm.next_review_date,pm.id DESC");$s->execute($p);return$s->fetchAll(PDO::FETCH_ASSOC);}
    public function find(int $id,string $role,int $user):?array{$p=[':id'=>$id];$scope=$this->scope($role,$user,$p);$s=$this->pdo->prepare("SELECT pm.*,ps.program_name,ps.program_code FROM program_manuals pm JOIN program_specifications ps ON ps.id=pm.program_specification_id WHERE pm.id=:id AND $scope");$s->execute($p);return$s->fetch(PDO::FETCH_ASSOC)?:null;}
    public function sections(int $id):array{$s=$this->pdo->prepare('SELECT * FROM program_manual_sections WHERE program_manual_id=:id ORDER BY sort_order,id');$s->execute([':id'=>$id]);return$s->fetchAll(PDO::FETCH_ASSOC);}
    public function programs(string $role,int $user):array{$p=[];if(in_array($role,['Admin','Quality Coordinator'],true)){$sql='SELECT id,program_name,program_code FROM program_specifications ORDER BY program_name';}else{$p[':user']=$user;$sql='SELECT id,program_name,program_code FROM program_specifications WHERE id IN (SELECT program_specification_id FROM user_program_access WHERE user_id=:user) ORDER BY program_name';}$s=$this->pdo->prepare($sql);$s->execute($p);return$s->fetchAll(PDO::FETCH_ASSOC);}
    public function save(array $f,?int$id):int{$cols=['program_specification_id','supersedes_manual_id','title','version_label','academic_period','declared_program_name','declared_credit_hours','declared_semesters','declared_plo_count','declared_course_count','status','prepared_by','approved_by','updated_date','approval_date','next_review_date','source_original_name','source_storage_key','source_sha256','source_mime','source_size','created_by_user_id'];if($id===null){$names=[];$marks=[];$p=[];foreach($cols as$c){$names[]="`$c`";$marks[]=":$c";$p[":$c"]=$f[$c]??null;}$this->pdo->prepare('INSERT INTO program_manuals('.implode(',',$names).') VALUES('.implode(',',$marks).')')->execute($p);return(int)$this->pdo->lastInsertId();}$set=[];$p=[':id'=>$id];foreach($cols as$c){if(array_key_exists($c,$f)){$set[]="`$c`=:$c";$p[":$c"]=$f[$c];}}$this->pdo->prepare('UPDATE program_manuals SET '.implode(',',$set).' WHERE id=:id')->execute($p);return$id;}
    public function replaceSections(int$id,array$sections):void{$this->pdo->prepare('DELETE FROM program_manual_sections WHERE program_manual_id=:id')->execute([':id'=>$id]);$s=$this->pdo->prepare('INSERT INTO program_manual_sections(program_manual_id,section_key,heading,content,sort_order) VALUES(:manual,:key,:heading,:content,:sort)');foreach($sections as$i=>$x)$s->execute([':manual'=>$id,':key'=>$x['section_key'],':heading'=>$x['heading'],':content'=>$x['content']??null,':sort'=>$x['sort_order']??$i+1]);}
    public function delete(int$id):void{$this->pdo->prepare('DELETE FROM program_manuals WHERE id=:id')->execute([':id'=>$id]);}
    public function revisions(int$program):array{$s=$this->pdo->prepare('SELECT id,title,version_label,status,approval_date,next_review_date FROM program_manuals WHERE program_specification_id=:program ORDER BY approval_date DESC,id DESC');$s->execute([':program'=>$program]);return$s->fetchAll(PDO::FETCH_ASSOC);}
    public function comparison(int$id):array{$sql="SELECT pm.id,pm.program_specification_id,ps.program_name specification_program_name,pm.declared_program_name manual_program_name,ps.total_credit_hours specification_credit_hours,pm.declared_credit_hours manual_credit_hours,(SELECT COUNT(*) FROM program_specification_plos p WHERE p.program_specification_id=ps.id) specification_plo_count,pm.declared_plo_count manual_plo_count,(SELECT COUNT(*) FROM program_specification_courses c WHERE c.program_specification_id=ps.id) specification_course_count,pm.declared_course_count manual_course_count,pm.declared_semesters manual_semesters FROM program_manuals pm JOIN program_specifications ps ON ps.id=pm.program_specification_id WHERE pm.id=:id";$s=$this->pdo->prepare($sql);$s->execute([':id'=>$id]);return$s->fetch(PDO::FETCH_ASSOC)?:[];}
    public function reconciliations(int$id):array{$s=$this->pdo->prepare('SELECT * FROM program_manual_reconciliations WHERE program_manual_id=:id');$s->execute([':id'=>$id]);$rows=[];foreach($s->fetchAll(PDO::FETCH_ASSOC)as$r)$rows[$r['field_key']]=$r;return$rows;}
    public function resolve(int$id,string$key,?string$spec,?string$manual,string$resolution,string$explanation,int$user):void{$sql="INSERT INTO program_manual_reconciliations(program_manual_id,field_key,specification_value,manual_value,resolution,explanation,resolved_by_user_id,resolved_at) VALUES(:id,:key,:spec,:manual,:resolution,:explanation,:user,NOW()) ON DUPLICATE KEY UPDATE specification_value=VALUES(specification_value),manual_value=VALUES(manual_value),resolution=VALUES(resolution),explanation=VALUES(explanation),resolved_by_user_id=VALUES(resolved_by_user_id),resolved_at=NOW()";$this->pdo->prepare($sql)->execute([':id'=>$id,':key'=>$key,':spec'=>$spec,':manual'=>$manual,':resolution'=>$resolution,':explanation'=>$explanation?:null,':user'=>$user]);}
    public function plos(int$id):array{$s=$this->pdo->prepare('SELECT * FROM program_manual_plos WHERE program_manual_id=:id ORDER BY sort_order,id');$s->execute([':id'=>$id]);return$s->fetchAll(PDO::FETCH_ASSOC);}
    public function courses(int$id):array{$s=$this->pdo->prepare('SELECT * FROM program_manual_courses WHERE program_manual_id=:id ORDER BY sort_order,id');$s->execute([':id'=>$id]);return$s->fetchAll(PDO::FETCH_ASSOC);}
    public function replacePlos(int$id,array$rows):void{$this->pdo->prepare('DELETE FROM program_manual_plos WHERE program_manual_id=:id')->execute([':id'=>$id]);$s=$this->pdo->prepare('INSERT INTO program_manual_plos(program_manual_id,plo_code,domain,description,sort_order) VALUES(:id,:code,:domain,:description,:sort)');foreach($rows as$i=>$r)$s->execute([':id'=>$id,':code'=>$r['code'],':domain'=>$r['domain']??null,':description'=>$r['description'],':sort'=>$i+1]);}
    public function replaceCourses(int$id,array$rows):void{$this->pdo->prepare('DELETE FROM program_manual_courses WHERE program_manual_id=:id')->execute([':id'=>$id]);$s=$this->pdo->prepare('INSERT INTO program_manual_courses(program_manual_id,semester_no,course_code,course_name,credit_hours,sort_order) VALUES(:id,:semester,:code,:name,:credits,:sort)');foreach($rows as$i=>$r)$s->execute([':id'=>$id,':semester'=>$r['semester']??null,':code'=>$r['code']??null,':name'=>$r['name'],':credits'=>$r['credits']??0,':sort'=>$i+1]);}
    public function replaceEntities(int$id,array$rows):void{$this->pdo->prepare('DELETE FROM program_manual_entities WHERE program_manual_id=:id')->execute([':id'=>$id]);$s=$this->pdo->prepare('INSERT INTO program_manual_entities(program_manual_id,entity_type,source_key,source_label,source_detail,sort_order) VALUES(:id,:type,:key,:label,:detail,:sort)');foreach($rows as$i=>$r)$s->execute([':id'=>$id,':type'=>$r['type'],':key'=>$r['key'],':label'=>$r['label'],':detail'=>$r['detail']??null,':sort'=>$i+1]);}
    public function detailedComparison(int$id):array{$m=$this->findUnscoped($id);if(!$m)return[];$p=(int)$m['program_specification_id'];$s=$this->pdo->prepare('SELECT plo_code,plo_domain domain,plo_text description FROM program_specification_plos WHERE program_specification_id=:id ORDER BY display_order,id');$s->execute([':id'=>$p]);$specPlos=$s->fetchAll(PDO::FETCH_ASSOC);$s=$this->pdo->prepare('SELECT course_code,course_title course_name,credit_hours,level_no semester_no FROM program_specification_courses WHERE program_specification_id=:id ORDER BY level_no,id');$s->execute([':id'=>$p]);return['spec_plos'=>$specPlos,'manual_plos'=>$this->plos($id),'spec_courses'=>$s->fetchAll(PDO::FETCH_ASSOC),'manual_courses'=>$this->courses($id)];}
    public function coordination(int$id):array{$m=$this->findUnscoped($id);if(!$m)return[];$staff=$this->pdo->prepare('SELECT COUNT(*) FROM program_staff WHERE department=:department OR college=:college');$staff->execute([':department'=>$m['department_name']??'__none__',':college'=>$m['college_name']??'__none__']);return['staff_count'=>(int)$staff->fetchColumn(),'committee_count'=>(int)$this->pdo->query("SELECT COUNT(*) FROM committees WHERE status='Active'")->fetchColumn()];}
    public function readiness(int$id):array{$m=$this->findUnscoped($id);if(!$m)return[];$checks=['approved'=>$m['status']==='Approved','source'=>!empty($m['source_sha256']),'review_date'=>!empty($m['next_review_date']),'sections'=>count($this->sections($id))>=6,'facts'=>!empty($m['declared_program_name'])&&$m['declared_credit_hours']!==null&&$m['declared_plo_count']!==null&&$m['declared_course_count']!==null,'plos'=>count($this->plos($id))===(int)$m['declared_plo_count'],'courses'=>count($this->courses($id))===(int)$m['declared_course_count'],'reconciled'=>count(array_filter($this->reconciliations($id),fn($r)=>$r['resolution']==='Unresolved'))===0&&count($this->reconciliations($id))>=4,'approval'=>$m['reconciliation_status']==='Approved'];$passed=count(array_filter($checks));return['checks'=>$checks,'score'=>(int)round($passed/count($checks)*100),'passed'=>$passed,'total'=>count($checks)];}
    public function setWorkflow(int$id,string$status,int$user,?string$note=null):void{if($status==='Pending Approval'){$sql='UPDATE program_manuals SET reconciliation_status=:status,reconciliation_submitted_by=:user,reconciliation_submitted_at=NOW(),reconciliation_note=:note WHERE id=:id';}else{$sql='UPDATE program_manuals SET reconciliation_status=:status,reconciliation_approved_by=:user,reconciliation_approved_at=NOW(),reconciliation_note=:note WHERE id=:id';}$this->pdo->prepare($sql)->execute([':status'=>$status,':user'=>$user,':note'=>$note,':id'=>$id]);}
    private function findUnscoped(int$id):?array{$s=$this->pdo->prepare('SELECT pm.*,ps.department_name,ps.college_name FROM program_manuals pm JOIN program_specifications ps ON ps.id=pm.program_specification_id WHERE pm.id=:id');$s->execute([':id'=>$id]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}
}
